<template>
 <div class="scene-root" ref="root" role="region" aria-label="可编辑三维架构画布">
  <div ref="canvasHost" class="canvas-host" />
  <div class="scene-labels">
   <button v-for="item in labels" :key="item.id" class="node-label" :class="{selected:item.id===selectedId,planned:item.state==='PLANNED'}" :style="{left:`${item.left}px`,top:`${item.top}px`,display:item.visible?'':'none'}" :aria-label="`选择节点 ${item.label}`" @click.stop="$emit('select',item.id)" @dblclick.stop="$emit('open',item.id)"><strong>{{item.label}}</strong><small>{{item.subtitle}}</small></button>
   <span v-for="item in groupLabels" :key="item.id" class="zone-label" :style="{left:`${item.left}px`,top:`${item.top}px`,color:item.color}">{{item.label}}</span>
  </div>
  <div v-if="failure" class="webgl-error" role="alert">{{failure}}<p>右侧资源列表和属性编辑仍可使用。</p></div>
  <div class="scene-help">{{tool==='move'?'拖动三维节点移动位置':tool==='connect'?'依次选择起点和终点创建连线':'拖动空白旋转 · 右键平移 · 滚轮缩放'}}<span>节点标签可点击；属性面板支持精确坐标。</span></div>
 </div>
</template>
<script setup>
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';
import * as THREE from '@/vendor/three/0.185.1/three.module.min.js';
import {OrbitControls} from '@/vendor/three/0.185.1/OrbitControls.js';
import {stages,stateLabel} from './graph';
const props=defineProps({nodes:Array,edges:Array,scope:String,preset:String,tool:String,selectedId:String});
const emit=defineEmits(['select','move','open']);
const root=ref(),canvasHost=ref(),labels=ref([]),groupLabels=ref([]),failure=ref('');
let renderer,scene,camera,controls,content,observer,drag,down;const groups=new Map();let labelAnchors=[],zoneAnchors=[];let alive=true;
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),ground=new THREE.Plane(new THREE.Vector3(0,1,0),0);
const materials=new Map();
function mat(color,options={}){const key=color+JSON.stringify(options);if(!materials.has(key))materials.set(key,new THREE.MeshStandardMaterial({color,roughness:.72,metalness:.12,...options}));return materials.get(key);}
function box(parent,w,h,d,x,y,z,color){const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(color));mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);return mesh;}
function cylinder(parent,r,h,x,y,z,color){const mesh=new THREE.Mesh(new THREE.CylinderGeometry(r,r,h,32),mat(color));mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);return mesh;}
function rack(g,color){box(g,2.2,4.2,1.9,0,2.15,0,'#f7f9fc');box(g,1.86,3.8,.1,0,2.16,1,'#253d58');for(let i=0;i<9;i++){box(g,1.55,.27,.14,0,.5+i*.4,1.08,'#8495a9');box(g,.09,.09,.03,.58,.5+i*.4,1.17,color);for(let j=0;j<4;j++)box(g,.16,.045,.03,-.53+j*.23,.5+i*.4,1.17,'#3b536c');}box(g,2.35,.16,2.05,0,.08,0,'#b7c8d9');}
function database(g,color){for(let i=0;i<3;i++){cylinder(g,1.22,.66,0,.55+i*.9,0,'#e4edf4');cylinder(g,1.24,.14,0,.92+i*.9,0,'#f9fcff');box(g,.6,.08,.05,0,.55+i*.9,1.23,color);}cylinder(g,1.12,.07,0,2.88,0,color);}
function service(g,color){box(g,2.5,2.4,1.8,0,1.3,0,'#f7faff');box(g,2.15,1.7,.09,0,1.25,.95,'#334d68');for(let i=0;i<3;i++){box(g,.42,.3,.06,-.65+i*.65,1.5,1.02,color);box(g,.42,.16,.06,-.65+i*.65,.94,1.02,'#b7c9d9');}box(g,2.8,.12,2.1,0,.08,0,'#b6c9d8');}
function client(g,color){box(g,3,1.95,.2,0,2.25,0,'#f6faff');box(g,2.7,1.65,.08,0,2.25,.15,'#2d4b67');box(g,1.8,.12,.1,-.25,2.5,.22,color);box(g,1.3,.09,.1,-.5,2.1,.22,'#dae6f1');box(g,.18,1.1,.25,0,.85,0,'#a7bfd4');box(g,2.2,.12,1.1,0,.25,.15,'#d8e5ed');}
function table(g,color){for(let i=0;i<3;i++){box(g,2.7,.38,2.2,0,.35+i*.6,0,'#f5f9fe');box(g,2.52,.13,.08,0,.38+i*.6,1.14,color);}box(g,2.3,.08,1.8,0,1.78,0,color);for(let i=0;i<3;i++)box(g,.035,.02,1.4,-.6+i*.6,1.83,0,'#eaf3ff');}
function disposeContent(){if(!content)return;content.traverse(o=>{o.geometry?.dispose();if(o.userData.ownedMaterial)o.material?.dispose();});scene.remove(content);groups.clear();}
function rebuild(){if(!renderer)return;disposeContent();content=new THREE.Group();scene.add(content);labelAnchors=[];zoneAnchors=[];
 const nodes=(props.nodes||[]).filter(n=>n.scope===props.scope);const zones=new Map();
 nodes.forEach(n=>{const zone=n.zone || (props.scope==='DATA'?n.layer:'未分区');if(!zones.has(zone))zones.set(zone,[]);zones.get(zone).push(n);});
 for(const [name,members] of zones){const bounds=new THREE.Box3();members.forEach(n=>bounds.expandByPoint(new THREE.Vector3(n.x,0,n.z)));const size=bounds.getSize(new THREE.Vector3()),center=bounds.getCenter(new THREE.Vector3());const color=stages.find(s=>s.id===name)?.color || '#799dbc';const p=box(content,Math.max(9,size.x+7),.1,Math.max(10,size.z+8),center.x,-.15,center.z,'#f9fbfe');p.receiveShadow=true;const edges=new THREE.LineSegments(new THREE.EdgesGeometry(p.geometry),new THREE.LineBasicMaterial({color,transparent:true,opacity:.4}));edges.position.copy(p.position);edges.userData.ownedMaterial=true;content.add(edges);zoneAnchors.push({id:name,label:stages.find(s=>s.id===name)?.name || name,position:new THREE.Vector3(center.x,.3,center.z+Math.max(10,size.z+8)/2+1),color});}
 for(const n of nodes){const g=new THREE.Group();g.position.set(n.x,0,n.z);g.userData.nodeId=n.id;content.add(g);groups.set(n.id,g);const color=stages.find(s=>s.id===n.layer)?.color || (n.engine?.toUpperCase()==='DORIS'?'#36adb7':'#608db8');
  if(n.kind==='HOST')rack(g,color);else if(n.kind==='DATABASE')database(g,color);else if(n.kind==='TABLE')table(g,color);else if(n.kind==='CLIENT')client(g,color);else service(g,color);
  const ring=new THREE.Mesh(new THREE.RingGeometry(1.8,1.87,48),new THREE.MeshBasicMaterial({color:n.id===props.selectedId?'#356bea':color,side:THREE.DoubleSide,transparent:true,opacity:n.id===props.selectedId?1:.35}));ring.rotation.x=-Math.PI/2;ring.position.y=.02;ring.userData.ownedMaterial=true;g.add(ring);
  labelAnchors.push({id:n.id,label:n.label,state:n.state,subtitle:[n.engine || n.kind,stateLabel(n.state)].join(' · '),group:g,height:n.kind==='HOST'?5.3:3.7});
 }
 for(const e of props.edges || []){const a=groups.get(e.source),b=groups.get(e.target);if(!a||!b)continue;const color=e.kind==='DIMENSION'?'#9780bb':e.state==='PLANNED'?'#8daabc':'#49a0b7';const start=a.position.clone().add(new THREE.Vector3(0,.6,0)),end=b.position.clone().add(new THREE.Vector3(0,.6,0));const mid=start.clone().lerp(end,.5);mid.y=e.kind==='DIMENSION'?3:1.9;const curve=new THREE.QuadraticBezierCurve3(start,mid,end);const geom=new THREE.BufferGeometry().setFromPoints(curve.getPoints(40));const line=new THREE.Line(geom,e.state==='PLANNED'?new THREE.LineDashedMaterial({color,dashSize:.6,gapSize:.35}):new THREE.LineBasicMaterial({color}));line.computeLineDistances();line.userData.ownedMaterial=true;content.add(line);const tip=curve.getPoint(.76);const arrow=new THREE.Mesh(new THREE.ConeGeometry(.18,.65,8),mat(color));arrow.position.copy(tip);arrow.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),curve.getTangent(.76).normalize());content.add(arrow);}
 render();}
function project(position){const v=position.clone().project(camera);return {left:(v.x+1)/2*root.value.clientWidth,top:(1-v.y)/2*root.value.clientHeight,visible:v.z>=-1&&v.z<=1&&Math.abs(v.x)<1.2&&Math.abs(v.y)<1.2};}
function render(){if(!renderer||!alive)return;renderer.render(scene,camera);labels.value=labelAnchors.map(a=>({...a,group:undefined,...project(a.group.position.clone().add(new THREE.Vector3(0,a.height,0)))}));groupLabels.value=zoneAnchors.map(a=>({...a,...project(a.position)}));}
function fit(){if(!renderer)return;const nodes=(props.nodes||[]).filter(n=>n.scope===props.scope);const bounds=new THREE.Box3();nodes.forEach(n=>bounds.expandByPoint(new THREE.Vector3(n.x,0,n.z)));if(bounds.isEmpty()){bounds.min.set(-20,0,-15);bounds.max.set(20,0,15);}const center=bounds.getCenter(new THREE.Vector3()),size=bounds.getSize(new THREE.Vector3());controls.target.copy(center);camera.position.copy(center).add(props.preset==='2d'?new THREE.Vector3(0,90,.001):props.preset==='2.5d'?new THREE.Vector3(30,90,55):new THREE.Vector3(48,62,75));camera.lookAt(center);const aspect=root.value.clientWidth/Math.max(1,root.value.clientHeight);const width=Math.max(38,size.x+22),height=Math.max(27,size.z+23);const frustum=Math.max(height,width/aspect)*1.13;camera.left=-frustum*aspect/2;camera.right=frustum*aspect/2;camera.top=frustum/2;camera.bottom=-frustum/2;camera.zoom=1;camera.updateProjectionMatrix();controls.enableRotate=props.preset!=='2d';controls.update();render();}
function resize(){if(!renderer)return;renderer.setSize(root.value.clientWidth,root.value.clientHeight);fit();}
function locate(event){const r=renderer.domElement.getBoundingClientRect();pointer.set((event.clientX-r.left)/r.width*2-1,-(event.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(pointer,camera);}
function hit(event){locate(event);const found=raycaster.intersectObjects([...groups.values()],true)[0];let o=found?.object;while(o && !o.userData.nodeId)o=o.parent;return o;}
function pointerDown(event){if(event.button!==0)return;down={x:event.clientX,y:event.clientY};const g=hit(event);if(props.tool==='move' && g){const point=new THREE.Vector3();raycaster.ray.intersectPlane(ground,point);drag={group:g,offset:g.position.clone().sub(point),id:g.userData.nodeId};controls.enabled=false;renderer.domElement.setPointerCapture(event.pointerId);}}
function pointerMove(event){if(!drag)return;locate(event);const point=new THREE.Vector3();if(raycaster.ray.intersectPlane(ground,point)){drag.group.position.copy(point.add(drag.offset));drag.group.position.y=0;render();}}
function pointerUp(event){if(drag){emit('move',{id:drag.id,x:Math.round(drag.group.position.x*2)/2,z:Math.round(drag.group.position.z*2)/2});drag=null;controls.enabled=true;}else if(down && Math.hypot(event.clientX-down.x,event.clientY-down.y)<5){const g=hit(event);if(g)emit('select',g.userData.nodeId);}down=null;}
function exportPng(){render();const a=document.createElement('a');a.download='qdata-architecture-3d.png';a.href=renderer.domElement.toDataURL('image/png');a.click();}
defineExpose({fit,exportPng});
onMounted(()=>{try{scene=new THREE.Scene();scene.background=new THREE.Color('#edf3f9');camera=new THREE.OrthographicCamera(-60,60,35,-35,.1,500);renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;canvasHost.value.appendChild(renderer.domElement);scene.add(new THREE.HemisphereLight(0xffffff,0xb8cadd,2.5));const light=new THREE.DirectionalLight(0xffffff,2.5);light.position.set(-35,70,45);light.castShadow=true;light.shadow.mapSize.set(2048,2048);light.shadow.camera.left=-100;light.shadow.camera.right=100;light.shadow.camera.top=100;light.shadow.camera.bottom=-100;light.shadow.normalBias=.08;scene.add(light);const grid=new THREE.GridHelper(260,130,'#d4e0ed','#e0e8f2');grid.position.y=-.28;scene.add(grid);const groundMesh=new THREE.Mesh(new THREE.PlaneGeometry(260,260),new THREE.ShadowMaterial({opacity:.12}));groundMesh.rotation.x=-Math.PI/2;groundMesh.position.y=-.27;groundMesh.receiveShadow=true;scene.add(groundMesh);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=false;controls.mouseButtons.LEFT=props.tool==='select'?THREE.MOUSE.ROTATE:null;controls.minZoom=.25;controls.maxZoom=5;controls.maxPolarAngle=Math.PI/2.05;controls.addEventListener('change',render);renderer.domElement.addEventListener('pointerdown',pointerDown);renderer.domElement.addEventListener('pointermove',pointerMove);renderer.domElement.addEventListener('pointerup',pointerUp);renderer.domElement.addEventListener('pointercancel',pointerUp);observer=new ResizeObserver(resize);observer.observe(root.value);rebuild();resize();}catch(e){failure.value='当前浏览器无法启用 WebGL 三维画布，请启用硬件加速后刷新。';}});
watch(()=>props.tool,()=>{if(controls)controls.mouseButtons.LEFT=props.tool==='select'?THREE.MOUSE.ROTATE:null;});
watch(()=>[props.nodes,props.edges,props.selectedId],rebuild,{deep:true});watch(()=>[props.scope,props.preset],()=>{rebuild();fit();});
onBeforeUnmount(()=>{alive=false;observer?.disconnect();controls?.dispose();disposeContent();scene?.traverse(o=>{o.geometry?.dispose();o.material?.dispose?.();});materials.forEach(m=>m.dispose());renderer?.dispose();});
</script>
<style scoped>
.scene-root{position:relative;width:100%;height:100%;min-height:560px;overflow:hidden;background:#edf3f9}.canvas-host{position:absolute;inset:0}.canvas-host :deep(canvas){display:block;touch-action:none}.scene-labels{position:absolute;inset:0;pointer-events:none}.node-label{position:absolute;transform:translate(-50%,-100%);pointer-events:auto;width:132px;max-width:150px;padding:7px 9px;background:rgba(255,255,255,.96);border:1px solid #d7e2ef;border-radius:5px;text-align:center;color:#28445f;cursor:pointer;font:inherit}.node-label strong{display:block;white-space:nowrap;text-overflow:ellipsis;overflow:hidden;font-size:12px}.node-label small{display:block;color:#576d82;font-size:10px;margin-top:4px}.node-label.selected{border-color:#376ef0;outline:2px solid #376ef022}.node-label.planned{border-style:dashed}.zone-label{position:absolute;transform:translate(-50%,-100%);font-size:12px;font-weight:600;white-space:nowrap;background:#f9fbfeed;padding:5px 8px;border-radius:4px}.scene-help{position:absolute;bottom:16px;left:18px;color:#56718b;font-size:12px;line-height:1.7;pointer-events:none}.scene-help span{display:block;font-size:11px}.webgl-error{position:absolute;inset:20%;padding:30px;background:white;color:#804524;text-align:center}
</style>
